import {CMAKE094_SOURCE,CMAKE094_FILES} from './pico-build094-example.js';
import {PICO_NATIVE_THREAD} from './pico-native-example.js';
import {CMAKE_SOURCE,CMAKE_FILES,DMA_PY} from './pico-build-examples.js';
import {PICO_SDK091_C,PICO_PY091} from './pico-language-examples.js';
import {emptyProject} from './templates.js';
import {PICO_BOARDS} from './pico-boards.js';
import {PICO_ADVANCED_CODE} from './pico-examples.js';
import {PICO_USB_EXAMPLES} from './pico-usb-examples.js';
export const PICO_EXAMPLES=[{id:'cmake094',name:'Pico C · Tarayıcı CMake / USB',detail:'Fonksiyon · koşul · üretilen başlık · USB stdio',language:'c'},{id:'thread093',name:'Pico MicroPython · Gerçek _thread',detail:'Özgün RP2 firmware · iki CPU · ortak nesne / kilit',language:'micropython'},{id:'cmake092',name:'Pico C · CMake hedef projesi',detail:'Kaynak / include / makro / static kütüphane',language:'c'},{id:'dma092',name:'Pico MicroPython · DMA / PIO',detail:'Gerçek DMA bus · Python tamponu · PIO DREQ',language:'micropython'},{id:'sdk091',name:'Pico C · Kuyruk / semafor / timer',detail:'İki çekirdek · tekrarlayan zamanlayıcı',language:'c'},{id:'py091',name:'Pico MicroPython · PIO / Timer',detail:'Gerçek PIO komutları · cooperative Timer',language:'micropython'},{id:'hid',name:'Pico C · USB HID klavye',detail:'Press/release · LED output report'},{id:'mouse',name:'Pico C · USB HID fare',detail:'X/Y · wheel/pan'},{id:'msc',name:'Pico C · USB MSC RAM disk',detail:'SCSI · 8 × 512B volatil blok'},{id:'dfu',name:'Pico C · USB DFU uygulaması',detail:'DNLOAD / UPLOAD · RAM staging'},{id:'usb',name:'Pico C · USB CDC terminal',detail:'USB descriptor / RX / TX echo'},{id:'advanced',name:'Pico C · Çift çekirdek + PIO/DMA',detail:'Core 1 FIFO · GP15 LED waveform'},{id:'radio',name:'Pico W · Sanal AP / UDP / BLE',detail:'Sanal laboratuvar; gerçek Internet değildir',wireless:true},{id:'blink',name:'Pico C · GP15 LED / UART0',detail:'Harici LED · gpio_put / sleep_ms'},{id:'buttons',name:'Pico C · GP14 buton / GP15 LED',detail:'Pull-up · GPIO okuma/yazma'}];
export function createPicoProject({name='Pico C projesi',board='pico',language='c',starter='blink',architecture='arm',pythonEngine='wasm'}={}){if(starter==='sdk095')starter='cmake094';if(!PICO_BOARDS[board]||!['c','micropython'].includes(language)||!['sdk095','cmake094','thread093','cmake092','dma092','sdk091','py091','empty','blink','buttons','usb','advanced','radio','hid','mouse','msc','dfu'].includes(starter))throw Error('Pico dil/başlangıç seçimi geçersiz.');if(starter==='thread093')pythonEngine='rp2-native';if(['py091','dma092'].includes(starter))pythonEngine='wasm';if(!['wasm','rp2-native'].includes(pythonEngine))throw Error('Pico Python motoru geçersiz.');const p=emptyProject();p.name=name;p.language=language;if(language==='micropython')p.settings.picoPythonEngine=pythonEngine;p.settings.picoArchitecture=architecture;if(architecture==='riscv'&&(PICO_BOARDS[board].mcu!=='RP2350'||language!=='c'))throw Error('Hazard3 yalnız Pico 2 C projelerinde kullanılabilir.');p.settings.probe='GPIO15';p.settings.tracePins=['GPIO14','GPIO0','GPIO1'];p.components=[{id:'mcu',type:'board',x:35,y:65,rotation:0,params:{model:board}},{id:'bb1',type:'breadboard',x:430,y:150,rotation:0,params:{}}];p.wires=[];p.code='#include <pico/stdlib.h>\n#include <stdio.h>\n\nint main(void) {\n    stdio_init_all();\n    gpio_init(15);\n    gpio_set_dir(15, GPIO_OUT);\n'+(starter==='buttons'?'    gpio_init(14);\n    gpio_pull_up(14);\n    while (1) {\n        gpio_put(15, !gpio_get(14));\n    }\n':starter==='empty'?'    while (1) { tight_loop_contents(); }\n':'    while (1) {\n        gpio_put(15, 1);\n        puts("Pico C LED ON");\n        sleep_ms(100);\n        gpio_put(15, 0);\n        puts("Pico C LED OFF");\n        sleep_ms(100);\n    }\n')+'}\n';if(starter==='radio'&&!PICO_BOARDS[board].wireless)throw Error('Sanal radyo örneği W/WH kartı gerektirir.');if(starter!=='empty'){p.components.push({id:'r1',type:'resistor',x:470,y:350,rotation:0,params:{ohms:330}},{id:'led1',type:'led',x:680,y:330,rotation:0,params:{color:'green'}});p.wires=[['mcu:GPIO15','r1:1'],['r1:2','led1:A'],['led1:K','mcu:GND']].map(([from,to],i)=>({id:'pico-w'+i,from,to,color:'#14b8a6',points:[]}));}if(starter==='buttons'){p.components.push({id:'sw',type:'button',x:540,y:470,rotation:0,params:{pressed:false}});p.wires.push({id:'pico-button0',from:'mcu:GPIO14',to:'sw:1',color:'#8b5cf6',points:[]},{id:'pico-button1',from:'sw:2',to:'mcu:GND',color:'#64748b',points:[]});}if(PICO_ADVANCED_CODE[starter])p.code=PICO_ADVANCED_CODE[starter];if(PICO_USB_EXAMPLES[starter])p.code=PICO_USB_EXAMPLES[starter];if(language==='micropython'){if(!['thread093','dma092','py091','blink','empty','buttons'].includes(starter))throw Error('MicroPython başlangıç örneği desteklenmiyor.');p.code=starter==='empty'?'# Pico MicroPython\n':starter==='buttons'?"from machine import Pin\nimport js\nled=Pin(15,Pin.OUT)\nbutton=Pin(14,Pin.IN,Pin.PULL_UP)\nwhile True:\n    led.value(not button.value())\n    await js.cf.sleep(20)\n":"from machine import Pin\nimport js\nled=Pin(15,Pin.OUT)\nwhile True:\n    led.toggle()\n    print('Pico MicroPython LED',led.value())\n    await js.cf.sleep(100)\n";}if(starter==='sdk091'){if(language!=='c')throw Error('C örneği gerekli.');p.code=PICO_SDK091_C;}if(starter==='py091'){if(language!=='micropython')throw Error('MicroPython örneği gerekli.');p.code=PICO_PY091;}if(starter==='cmake094'){if(language!=='c')throw Error('C projesi gerekli.');p.code=CMAKE094_SOURCE;p.files=CMAKE094_FILES.map(f=>({...f}));}if(starter==='cmake092'){if(language!=='c')throw Error('C projesi gerekli.');p.code=CMAKE_SOURCE;p.files=CMAKE_FILES.map(f=>({...f}));}if(starter==='dma092'){if(language!=='micropython')throw Error('MicroPython projesi gerekli.');p.code=DMA_PY;}if(language==='micropython'&&pythonEngine==='rp2-native'){p.code=starter==='thread093'?PICO_NATIVE_THREAD:starter==='empty'?'# Native RP2 MicroPython\n':starter==='buttons'?"from machine import Pin\nimport time\nled=Pin(15,Pin.OUT)\nbutton=Pin(14,Pin.IN,Pin.PULL_UP)\nwhile True:\n    led.value(not button.value())\n    time.sleep_ms(20)\n":"from machine import Pin\nimport time\nled=Pin(15,Pin.OUT)\nwhile True:\n    led.toggle()\n    print('Native RP2 LED',led.value())\n    time.sleep_ms(100)\n";}return p;}
